import { boolean, integer, jsonb, pgTable, text, timestamp } from 'drizzle-orm/pg-core';
import { createId } from '../ids';
import type { JsonValue } from '../json';

// Exclusive physical projections. Historical SQL owns FK/unique/status/immutable
// guards; no schema registration or DDL is generated by this module.
export const recruitmentApplications = pgTable('HrRecruitmentApplication', {
  id: text('id').primaryKey(), noticeRuleId: text('noticeRuleId').notNull(),
  applicantUserId: text('applicantUserId').notNull(), cpf: text('cpf').notNull(),
  roleCode: text('roleCode').notNull(), number: integer('number').notNull(),
  status: text('status').notNull().default('RECEBIDA'),
  snapshot: jsonb('snapshot').$type<JsonValue>().notNull(), requestHash: text('requestHash').notNull(),
  decision: text('decision'), decidedById: text('decidedById'),
  createdAt: timestamp('createdAt', { precision: 3 }).notNull().defaultNow(),
  decidedAt: timestamp('decidedAt', { precision: 3 }),
});
export const recruitmentRules = pgTable('HrPayrollRule', {
  id: text('id').primaryKey().$defaultFn(createId), ruleSetId: text('ruleSetId').notNull(),
  code: text('code').notNull(), name: text('name').notNull(), category: text('category').notNull(),
  valueType: text('valueType').notNull(), isActive: boolean('isActive').notNull().default(true),
  value: jsonb('value').$type<JsonValue>().notNull(),
  createdAt: timestamp('createdAt', { precision: 3 }).notNull().defaultNow(),
  updatedAt: timestamp('updatedAt', { precision: 3 }).notNull().$defaultFn(() => new Date()).$onUpdateFn(() => new Date()),
});
export const recruitmentRuleSets = pgTable('HrPayrollRuleSet', {
  id: text('id').primaryKey(), status: text('status').notNull(),
  effectiveFrom: timestamp('effectiveFrom', { precision: 3 }).notNull(),
  effectiveUntil: timestamp('effectiveUntil', { precision: 3 }),
});
export const recruitmentDocuments = pgTable('Document', {
  id: text('id').primaryKey(), status: text('status').notNull(), personId: text('personId'),
});
export const recruitmentDocumentVersions = pgTable('DocumentVersion', {
  id: text('id').primaryKey(), documentId: text('documentId').notNull(), status: text('status').notNull(),
});
export const recruitmentUsers = pgTable('Usuario', {
  id: text('id').primaryKey(), ativo: boolean('ativo').notNull(), perfilId: text('perfilId').notNull(),
});
export const recruitmentProfiles = pgTable('ConfiguracaoPerfil', {
  id: text('id').primaryKey(), ativo: boolean('ativo').notNull(),
});
